"""Domain model for a single grain storage silo."""
from dataclasses import dataclass


@dataclass
class Silo:
    """A single grain storage silo and its current contents.

    Moisture and test weight describe the bulk grain currently held in the
    silo. They are assumed uniform within the silo (no internal
    stratification modeling), which matches how most elevators track
    inventory day to day.
    """

    id: str
    name: str
    capacity_bu: float
    current_bu: float
    moisture_pct: float
    test_weight_lbs_bu: float
    min_reserve_bu: float = 0.0
    max_discharge_rate_bu_per_min: float = 2000.0

    def __post_init__(self) -> None:
        if self.capacity_bu <= 0:
            raise ValueError(f"{self.id}: capacity_bu must be positive")
        if not (0 <= self.current_bu <= self.capacity_bu):
            raise ValueError(f"{self.id}: current_bu out of range for capacity")
        if self.min_reserve_bu < 0:
            raise ValueError(f"{self.id}: min_reserve_bu cannot be negative")
        if self.max_discharge_rate_bu_per_min <= 0:
            raise ValueError(f"{self.id}: discharge rate must be positive")

    @property
    def available_bu(self) -> float:
        """Bushels that can be pulled without breaching the reserve floor."""
        return max(0.0, self.current_bu - self.min_reserve_bu)

    def withdraw(self, amount_bu: float) -> None:
        """Remove amount_bu of grain from the silo.

        Raises ValueError if amount_bu exceeds what is available above the
        reserve floor.
        """
        if amount_bu < 0:
            raise ValueError("amount_bu cannot be negative")
        if amount_bu > self.available_bu + 1e-9:
            raise ValueError(
                f"{self.id}: cannot withdraw {amount_bu:.1f} bu, only "
                f"{self.available_bu:.1f} bu available above reserve"
            )
        self.current_bu -= amount_bu

    def discharge_minutes(self, amount_bu: float) -> float:
        """Estimated time to discharge amount_bu at this silo's rated flow."""
        return amount_bu / self.max_discharge_rate_bu_per_min

"""Inventory tracking for the set of silos that make up a blending yard."""
from typing import Dict, Iterable, List, Optional

from silo import Silo


class SiloYard:
    """Holds every silo at a facility and answers inventory queries."""

    def __init__(self, silos: Iterable[Silo]):
        self._silos: Dict[str, Silo] = {}
        for silo in silos:
            if silo.id in self._silos:
                raise ValueError(f"duplicate silo id: {silo.id}")
            self._silos[silo.id] = silo

    def get(self, silo_id: str) -> Silo:
        try:
            return self._silos[silo_id]
        except KeyError:
            raise KeyError(f"no such silo: {silo_id}") from None

    def all_silos(self) -> List[Silo]:
        return list(self._silos.values())

    def total_available_bu(self, silo_ids: Optional[Iterable[str]] = None) -> float:
        """Sum of available_bu across the given silo ids, or all silos if None."""
        return sum(s.available_bu for s in self._select(silo_ids))

    def weighted_moisture(self, silo_ids: Optional[Iterable[str]] = None) -> float:
        """Bushel-weighted average moisture across the given (or all) silos.

        Weighting is by current_bu (grain actually on hand), not available_bu,
        since this describes the quality of stored inventory rather than the
        withdrawable portion -- it's a reporting figure, not a planning one.
        """
        silos = self._select(silo_ids)
        total_bu = sum(s.current_bu for s in silos)
        if total_bu <= 0:
            raise ValueError("cannot compute weighted moisture with zero inventory")
        return sum(s.current_bu * s.moisture_pct for s in silos) / total_bu

    def weighted_test_weight(self, silo_ids: Optional[Iterable[str]] = None) -> float:
        silos = self._select(silo_ids)
        total_bu = sum(s.current_bu for s in silos)
        if total_bu <= 0:
            raise ValueError("cannot compute weighted test weight with zero inventory")
        return sum(s.current_bu * s.test_weight_lbs_bu for s in silos) / total_bu

    def _select(self, silo_ids: Optional[Iterable[str]]) -> List[Silo]:
        if silo_ids is None:
            return self.all_silos()
        return [self.get(sid) for sid in silo_ids]
